final readonly class ProductSearch
{
    public function __construct(private HttpClientInterface $searchClient)
    {
    }

    /** @return array{hits: list<array>, brands: list<array>} */
    public function search(string $text, ?string $brand = null): array
    {
        $body = [
            'size' => 20,
            'query' => ['bool' => [
                'must' => [['multi_match' => [
                    'query' => $text,
                    'fields' => ['name^3', 'description'],
                ]]],
                'filter' => [['term' => ['in_stock' => true]]],
            ]],
            'aggs' => [
                'brands' => ['terms' => ['field' => 'brand', 'size' => 10]],
            ],
        ];
        if (null !== $brand) {
            $body['post_filter'] = ['term' => ['brand' => $brand]];
        }

        $data = $this->searchClient
            ->request('POST', '/products/_search', ['json' => $body])
            ->toArray();

        return [
            'hits' => array_column($data['hits']['hits'], '_source'),
            'brands' => $data['aggregations']['brands']['buckets'],
        ];
    }
}

-- 1. Once, in a migration: a column of terms the database keeps up to date
ALTER TABLE product ADD search_vector tsvector GENERATED ALWAYS AS (
    setweight(to_tsvector('english', coalesce(name, '')), 'A') ||
    setweight(to_tsvector('english', coalesce(description, '')), 'B')
) STORED;
CREATE INDEX product_search_idx ON product USING GIN (search_vector);

-- 2. Every search: "samsung phones" finds the Samsung Galaxy A15 Phone
SELECT id, name, ts_rank(search_vector, q) AS score
FROM product, websearch_to_tsquery('english', 'samsung phones') AS q
WHERE search_vector @@ q
ORDER BY score DESC
LIMIT 20;

#[Route('/api/products', methods: ['POST'])]
public function create(#[MapRequestPayload] ProductInput $input): JsonResponse
{
    $product = Product::fromInput($input);
    $this->em->persist($product);
    $this->em->flush();                          // 1. write to the database

    $this->searchClient->request('PUT', '/products/_doc/'.$product->getId(), [
        'json' => $product->toSearchDocument(),  // 2. write to the search index
    ])->getContent();

    return $this->json(['id' => $product->getId()], 201);
}

