final readonly class ProductCatalog
{
    public function __construct(
        private EntityManagerInterface $em,
        private MessageBusInterface $bus,
    ) {
    }

    public function changePrice(Product $product, int $priceInCents): void
    {
        $product->changePrice($priceInCents);
        $this->em->flush();                                         // 1. truth first

        $this->bus->dispatch(new IndexProduct($product->getId()));  // 2. then the news
    }
}

#[AsMessageHandler]
final readonly class IndexProductHandler
{
    public function __construct(
        private ProductRepository $products,
        private HttpClientInterface $searchClient,
    ) {
    }

    public function __invoke(IndexProduct $message): void
    {
        $url = '/products/_doc/'.$message->productId;
        $product = $this->products->find($message->productId);

        if (null === $product || !$product->isPublished()) {
            $status = $this->searchClient->request('DELETE', $url)->getStatusCode();
            if (!\in_array($status, [200, 404], true)) {
                throw new \RuntimeException('Search delete failed: '.$status);
            }

            return;
        }

        $this->searchClient->request('PUT', $url, [
            'json' => $product->toSearchDocument(),
        ])->getContent();
    }
}

final readonly class ProductReindexer
{
    public function __construct(
        private EntityManagerInterface $em,
        private HttpClientInterface $searchClient,
    ) {
    }
    public function fill(string $index): void          // e.g. products_v2
    {
        $query = $this->em->createQuery(
            'SELECT p FROM App\Entity\Product p WHERE p.published = true ORDER BY p.id'
        );
        $lines = '';
        foreach ($query->toIterable() as $i => $product) {
            $lines .= json_encode(['index' => ['_id' => $product->getId()]])."\n"
                .json_encode($product->toSearchDocument())."\n";
            if (0 === ($i + 1) % 500) {
                $this->send($index, $lines);
                $lines = '';
                $this->em->clear();
            }
        }
        if ('' !== $lines) {
            $this->send($index, $lines);
        }
    }

    private function send(string $index, string $lines): void
    {
        $result = $this->searchClient->request('POST', "/$index/_bulk", [
            'headers' => ['Content-Type' => 'application/x-ndjson'],
            'body' => $lines,
        ])->toArray();
        $result['errors'] && throw new \RuntimeException('Bulk indexing failed.');
    }
}

