final readonly class TopProducts
{
    public function __construct(
        private CacheInterface $cache,
        private ProductRepository $products,
    ) {
    }

    /** @return list<array{id: int, name: string, sold: int}> */
    public function forHomepage(): array
    {
        return $this->cache->get('top_products.v1', function (ItemInterface $item): array {
            $item->expiresAfter(600);      // stale after 10 minutes

            return $this->products->findTopSelling(10);   // slow query, only on a miss
        });
    }
}

