final readonly class ProductCache
{
    public function __construct(
        private TagAwareCacheInterface $cache,
        private ProductRepository $products,
    ) {
    }

    public function view(int $id): array
    {
        return $this->cache->get("product.v1.$id", function (ItemInterface $item) use ($id) {
            $product = $this->products->find($id) ?? throw new NotFoundHttpException();
            $item->expiresAfter(3600);
            $item->tag(["product_$id", 'category_'.$product->getCategoryId()]);

            return ProductView::from($product)->toArray();
        });
    }

    public function afterPriceChanged(int $id): void
    {
        $this->cache->invalidateTags(["product_$id"]);  // call it after the flush
    }

    public function categoryList(int $catId): array
    {
        return $this->cache->get("cat.v1.$catId", function (ItemInterface $item) use ($catId) {
            $rows = $this->products->summariesIn($catId);   // one page, 20 products
            $item->expiresAfter(300);
            $item->tag(array_map(fn (array $r) => 'product_'.$r['id'], $rows));

            return $rows;
        });
    }
}

public function changePrice(Product $product, int $cents): void
{
    $product->changePrice($cents);
    $this->em->flush();                               // 1. write the truth first

    $this->cache->invalidateTags(['product_'.$product->getId()]);  // 2. then delete
}

public function forHomepage(): array
{
    return $this->cache->get(
        'top_products.v1',
        function (ItemInterface $item): array {
            // jitter: 600 seconds + a random 0 to 120 seconds
            $item->expiresAfter(600 + random_int(0, 120));

            return $this->products->findTopSelling(10);
        },
        beta: 1.0,    // early expiration; 0 turns it off, \INF rebuilds right now
    );
}

public function get(): array
{
    $entry = $this->cache->get('top.v1', $this->fresh(...));
    if ($entry['soft'] > time()) {
        return $entry['data'];
    }

    $lock = $this->locks->createLock('refresh.top.v1', 30);
    if ($lock->acquire()) {          // not blocking: either I got it or I didn't
        try {
            $entry = $this->cache->get('top.v1', $this->fresh(...), beta: \INF);
        } finally {
            $lock->release();
        }
    }

    return $entry['data'];           // without the lock, the nearly stale value will do
}

private function fresh(ItemInterface $item): array
{
    $item->expiresAfter(3600);       // hard TTL
    $data = $this->products->findTopSelling(10);

    return ['soft' => time() + 300, 'data' => $data];   // soft TTL
}

$lock = $this->locks->createLock('rebuild.top');
$lock->acquire(true);                 // if it can't get it, it waits forever

$value = $this->products->findTopSelling(10);
$this->cache->get('top.v1', fn () => $value);
$lock->release();                     // never reached if an exception is thrown

$lock = $this->locks->createLock('rebuild.top', ttl: 30);

if (!$lock->acquire()) {
    return $this->staleCopy->get() ?? $this->waitBriefly();   // brief wait or stale value
}

try {
    return $this->rebuildAndStore();
} finally {
    $lock->release();
}

#[Route('/api/products/{id}', methods: ['GET'])]
#[Cache(maxage: 60, smaxage: 600, public: true, staleWhileRevalidate: 120)]
public function show(Product $product, Request $request): JsonResponse
{
    $response = new JsonResponse();
    $response->setEtag(md5($product->getId().'|'.$product->getUpdatedAt()->format('U.u')));

    if ($response->isNotModified($request)) {
        return $response;            // 304: returned without doing the heavy work
    }

    return $response->setData(ProductView::from($product)->toArray());
}

